const fs=require('fs'),crypto=require('crypto'),cp=require('child_process');
const p='experiments/parseatlas_secp256k1/data/p5_codegen_20260905.json',j=JSON.parse(fs.readFileSync(p,'utf8'));
let n=0;const errors=[];function ck(c,m){n++;if(!c)errors.push(m);}const sha=s=>crypto.createHash('sha256').update(s).digest('hex');
const bin='/tmp/parseatlas-p5-field-product.3Z4xU1/p5_compare_gcc';
ck(j.binary.path===bin&&sha(fs.readFileSync(bin))===j.binary.sha256,'binary');
const nm=cp.execFileSync('nm',['-S','-n','-C',bin],{encoding:'utf8'}).split('\n');
for(const s of j.disassembly_slices){
 ck(/^0x[0-9a-f]+$/.test(s.start)&&/^0x[0-9a-f]+$/.test(s.end_exclusive),'addresssyntax');
 ck(sha(s.disassembly)===s.disassembly_sha256,'retainedslicehash:'+s.name);
 const real=cp.execFileSync('objdump',['-d','-C','--no-show-raw-insn','--start-address='+s.start,'--stop-address='+s.end_exclusive,bin],{encoding:'utf8'});
 ck(real===s.disassembly,'actualslice:'+s.name);
 ck(nm.includes(s.nm_line),'actualnm:'+s.name);
 ck(parseInt(s.end_exclusive)-parseInt(s.start)===s.size_decimal&&parseInt(s.size_hex)===s.size_decimal,'size:'+s.name);
}
const ins=s=>s.disassembly.split('\n').flatMap(line=>{const m=line.match(/^\s*([0-9a-f]+):\s+(\S+)(?:\s+(.*))?$/);return m?[{address:parseInt(m[1],16),op:m[2],args:m[3]||'',line}]:[];});
const norm=s=>ins(s).map(i=>{let a=i.args,rip=a.match(/#\s*([0-9a-f]+)/);a=a.replace(/\s*#.*$/,'').replace(/\s*<.*$/,'');if(rip&&/%rip/.test(a))a=a.replace(/-?0x[0-9a-f]+\(%rip\)/,'RIP_TARGET_'+rip[1]);if(/^(?:j\w+|call\w*)$/.test(i.op))a=a.replace(/^([0-9a-f]+)/,h=>{let v=parseInt(h,16);return v>=parseInt(s.start)&&v<parseInt(s.end_exclusive)?'SELF+'+(v-parseInt(s.start)).toString(16):'ABS_'+h;});return(i.op+' '+a).trim();});
for(const x of j.normalized_pairs.comparisons){let a=j.disassembly_slices.find(s=>s.start===x.left),b=j.disassembly_slices.find(s=>s.start===x.right),la=norm(a),lb=norm(b),ds=[];for(let i=0;i<Math.max(la.length,lb.length);i++)if(la[i]!==lb[i])ds.push({index:i,left:la[i],right:lb[i]});ck(JSON.stringify(ds)===JSON.stringify(x.differences),'pairdiff:'+x.left);ck((ds.length===0)===x.equal,'pairequal');ck(sha(la.join('\n')+'\n')===x.left_sequence_sha256&&sha(lb.join('\n')+'\n')===x.right_sequence_sha256,'pairhash');ck(la.length===x.instruction_count&&lb.length===x.instruction_count,'paircount');}
for(const f of j.full_jobs){const s=j.disassembly_slices.find(x=>x.start===f.start),ii=ins(s);ck(ii.length===f.static_instruction_count,'jobcount');ck(f.output_bytes_stored===128&&f.output_store_instructions.length===4,'stores128');ck(sha(norm(s).join('\n')+'\n')===f.normalized_instruction_sequence_sha256,'jobnorm');}
for(const w of j.loop_and_phase_windows){const s=j.disassembly_slices.find(s=>s.name===w.parent_symbol);const text=ins(s).filter(i=>i.address>=parseInt(w.start)&&i.address<parseInt(w.end_exclusive)).map(i=>i.line).join('\n')+'\n';ck(text===w.instructions,'window:'+w.name);}
process.stdout.write(JSON.stringify({schema:'parseatlas_p5_codegen_replay_v1',status:errors.length?'fail':'pass',checks:n,slices:65,symbols:65,jobs:20,pairs:6,phase_windows:14,errors}));
